from collections import defaultdict

def c2(x):
	return x * (x - 1) // 2

def c3(x):
	return x * (x - 1) * (x - 2) // 6
while True:
	try:
		counts = defaultdict(int)
		n = int(input().strip())
		for _ in range(n):
			(x, y) = map(int, input().strip().split())
			counts[x % 4, y % 4] += 1
		ans = c3(counts[0, 0]) + c3(counts[0, 2]) + c3(counts[2, 0]) + c3(counts[2, 2])
		ans += c2(counts[0, 0]) * (n - counts[0, 0]) + c2(counts[0, 2]) * (n - counts[0, 2]) + c2(counts[2, 0]) * (n - counts[2, 0]) + c2(counts[2, 2]) * (n - counts[2, 2])
		print(ans)
	except EOFError:
		break
